WITH matched_keys AS (SELECT id FROM suppliers EXCEPT SELECT id FROM suppliers WHERE country IN ('TH', 'JP', 'SG')), reconciled AS (SELECT s.* FROM suppliers s INNER JOIN matched_keys k ON s.id = k.id) SELECT CASE WHEN rating >= 3.6 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, ROUND(AVG(rating), 2) AS avg_rating, COUNT_IF(city = 'London') AS london_events FROM reconciled GROUP BY 1 HAVING london_events >= 1 ORDER BY rating_tier
